function createPaymentRegistry() {
  const strategies = new Map();
  return {
    register(name, fn) {
      strategies.set(name, fn);
    },
    resolve(name) {
      const fn = strategies.get(name);
      if (!fn) throw new Error('No strategy for ' + name);
      return fn;
    },
  };
}

function chargeWith(strategies, method, amountCents) {
  const fn = strategies[method];
  if (!fn) throw new Error('Unknown payment method: ' + method);
  return fn(amountCents);
}

