function withRetry(fn, maxAttempts) {
  return function () {
    let lastError;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        return fn();
      } catch (err) {
        lastError = err;
      }
    }
    throw lastError;
  };
}

function withLogging(fn, log) {
  return function (...args) {
    const result = fn(...args);
    log(result);
    return result;
  };
}

