function createEventBus() {
  let listeners = [];
  return {
    subscribe(fn) {
      listeners.push(fn);
      return function unsubscribe() {
        listeners = listeners.filter((l) => l !== fn);
      };
    },
    notify(data) {
      for (const fn of listeners) fn(data);
    },
  };
}

function adaptLegacyProcessor(legacy) {
  return {
    charge(amountCents) {
      const dollars = Math.floor(amountCents / 100);
      const cents = amountCents % 100;
      return legacy.legacyPay(dollars, cents);
    },
  };
}

function adaptDecimalProcessor(legacy) {
  return {
    charge(amountCents) {
      const amount = amountCents / 100;
      return legacy.pay({ amount, currency: 'USD' });
    },
  };
}
